mapper.sql:
WHERE ( 1=1
log_content LIKE CONCAT('%', #{keyWord}, '%') OR log_remark LIKE CONCAT('%', #{keyWord}, '%') OR module_name LIKE CONCAT('%', #{keyWord}, '%') OR href_name LIKE CONCAT('%', #{keyWord}, '%') OR control_name LIKE CONCAT('%', #{keyWord}, '%')
) AND (log_date < #{lastTime} OR (log_date = #{lastTime} AND id < #{lastId})) ORDER BY log_date DESC, id DESC LIMIT #{pageSize}

